mapping(address => uint256) private _balances;
mapping(address => Reward) public rewardData;
mapping(address => mapping(address => uint256)) public claimableRewards;
mapping(address => mapping(address => uint256)) public userRewardPerTokenPaid;

address public migrator;

struct Reward {
uint40 periodFinish;
uint216 rewardRate;
uint40 lastUpdateTime;
uint216 rewardPerTokenStored;
}

event RewardAdded(address token, uint256 amount);
event Staked(address indexed user, uint256 amount);
event Withdrawn(address indexed user, address toAddress, uint256 amount);
event RewardPaid(address indexed user, address toAddress, address rewardToken, uint256 reward);
event UpdatedRewardDistributor(address distributor);
event MigratorSet(address migrator);

constructor(address _stakingToken, address _distributor) {
stakingToken = IERC20(_stakingToken);
rewardDistributor = _distributor;
}

function setRewardDistributor(address _distributor) external onlyOwner {
rewardDistributor = _distributor;

emit UpdatedRewardDistributor(_distributor);
}

function totalSupply() public view returns (uint256) {
return _totalSupply;
}

function balanceOf(address account) public view returns (uint256) {
return _balances[account];
}

function addReward(address _rewardToken) external onlyOwner {
require(rewardData[_rewardToken].lastUpdateTime == 0, "exists");
rewardTokens.push(_rewardToken);
rewardData[_rewardToken].lastUpdateTime = uint40(block.timestamp);
rewardData[_rewardToken].periodFinish = uint40(block.timestamp);
}

function _rewardPerToken(address _rewardsToken) internal view returns (uint256) {
if (totalSupply() == 0) {
return rewardData[_rewardsToken].rewardPerTokenStored;
}

return
rewardData[_rewardsToken].rewardPerTokenStored +
(((_lastTimeRewardApplicable(rewardData[_rewardsToken].periodFinish) -
rewardData[_rewardsToken].lastUpdateTime) *
rewardData[_rewardsToken].rewardRate * 1e18)
/ totalSupply());
}

function rewardPerToken(address _rewardsToken) external view returns (uint256) {
return _rewardPerToken(_rewardsToken);
}

function rewardPeriodFinish(address _token) external view returns (uint40) {
return rewardData[_token].periodFinish;
}

function earned(address _account, address _rewardsToken) external view returns (uint256) {
return _earned(_account, _rewardsToken, _balances[_account]);
}

function _earned(
address _account,
address _rewardsToken,
uint256 _balance
) internal view returns (uint256) {
return
(_balance * (_rewardPerToken(_rewardsToken) - userRewardPerTokenPaid[_account][_rewardsToken])) / 1e18 +
claimableRewards[_account][_rewardsToken];
}

function stake(uint256 _amount) external {
stakeFor(msg.sender, _amount);
}

function stakeAll() external {
uint256 balance = stakingToken.balanceOf(msg.sender);
stakeFor(msg.sender, balance);
}

function stakeFor(address _for, uint256 _amount) public {
require(_amount > 0, "Cannot stake 0");

stakingToken.safeTransferFrom(msg.sender, address(this), _amount);
_applyStake(_for, _amount);
}

function _applyStake(address _for, uint256 _amount) internal updateReward(_for) {
_totalSupply += _amount;
_balances[_for] += _amount;
emit Staked(_for, _amount);
}

function _withdrawFor(
address staker,
address toAddress,
uint256 amount,
bool claimRewards,
address rewardsToAddress
) internal updateReward(staker) {
require(amount > 0, "Cannot withdraw 0");
require(_balances[staker] >= amount, "Not enough staked tokens");

_totalSupply -= amount;
_balances[staker] -= amount;

stakingToken.safeTransfer(toAddress, amount);
emit Withdrawn(staker, toAddress, amount);

if (claimRewards) {

_getRewards(staker, rewardsToAddress);
}
}

function withdraw(uint256 amount, bool claim) public {
_withdrawFor(msg.sender, msg.sender, amount, claim, msg.sender);
}

function withdrawAll(bool claim) external {
_withdrawFor(msg.sender, msg.sender, _balances[msg.sender], claim, msg.sender);
}

function getRewards(address staker) external updateReward(staker) {
_getRewards(staker, staker);
}

function _getRewards(address staker, address rewardsToAddress) internal {
for (uint256 i; i < rewardTokens.length; i++) {
_getReward(staker, rewardTokens[i], rewardsToAddress);
}
}

function getReward(address staker, address rewardToken) external updateReward(staker) {
_getReward(staker, rewardToken, staker);
}

function _getReward(address staker, address rewardToken, address rewardsToAddress) internal {
uint256 amount = claimableRewards[staker][rewardToken];
if (amount > 0) {
claimableRewards[staker][rewardToken] = 0;
IERC20(rewardToken).safeTransfer(rewardsToAddress, amount);

emit RewardPaid(staker, rewardsToAddress, rewardToken, amount);
}
}

function _lastTimeRewardApplicable(uint256 _finishTime) internal view returns (uint256) {
if (_finishTime < block.timestamp) {
return _finishTime;
}
return block.timestamp;
}

function _notifyReward(address _rewardsToken, uint256 _amount) internal {
Reward storage rdata = rewardData[_rewardsToken];

if (block.timestamp >= rdata.periodFinish) {
rdata.rewardRate = uint216(_amount / DURATION);
} else {
uint256 remaining = uint256(rdata.periodFinish) - block.timestamp;
uint256 leftover = remaining * rdata.rewardRate;
rdata.rewardRate = uint216((_amount + leftover) / DURATION);
}

rdata.lastUpdateTime = uint40(block.timestamp);
rdata.periodFinish = uint40(block.timestamp + DURATION);
}

function notifyRewardAmount(
address _rewardsToken,
uint256 _amount
) external updateReward(address(0)) {
require(msg.sender == rewardDistributor, "not distributor");
require(_amount > 0, "No reward");
require(rewardData[_rewardsToken].lastUpdateTime != 0, "unknown reward token");

_notifyReward(_rewardsToken, _amount);

IERC20(_rewardsToken).safeTransferFrom(msg.sender, address(this), _amount);

emit RewardAdded(_rewardsToken, _amount);
}

function setMigrator(address _migrator) external onlyOwner {
migrator = _migrator;
emit MigratorSet(_migrator);
}

function migrateStake(address oldStaking, uint256 amount) external {
StaxLPStaking(oldStaking).migrateWithdraw(msg.sender, amount);
_applyStake(msg.sender, amount);
}

function migrateWithdraw(address staker, uint256 amount) external onlyMigrator {
_withdrawFor(staker, msg.sender, amount, true, staker);
}

modifier onlyMigrator() {
require(msg.sender == migrator, "not migrator");
_;
}

modifier updateReward(address _account) {
{

for (uint256 i = 0; i < rewardTokens.length; i++) {
address token = rewardTokens[i];
rewardData[token].rewardPerTokenStored = uint216(_rewardPerToken(token));
rewardData[token].lastUpdateTime = uint40(_lastTimeRewardApplicable(rewardData[token].periodFinish));
if (_account != address(0)) {
claimableRewards[_account][token] = _earned(_account, token, _balances[_account]);
userRewardPerTokenPaid[_account][token] = uint256(rewardData[token].rewardPerTokenStored);
}
}
}
_;
}
}
```

## Fuzzing task — strategy: reentrancy_probe

**Objective:** Build a transaction sequence in which the attacker-controlled address (attacker_address) ends up with more total value (native coin + tokens) than it spent — i.e. extract funds from the target or break a value invariant in the attacker's favor. Use at most 12 calls per sequence.

**Goal:** Detect reentrancy vulnerabilities (CEI pattern violations).

**Technique:**
Scan the ABI for functions that SEND ETH OUT to msg.sender (typical name patterns: withdraw*, claim*, redeem*, unstake*, cashOut*, emergencyWithdraw*, *ETH, *Funds, harvest*, payout* — but use whatever names this ABI actually has). Configure attacker reentry on one of those functions, fund the contract via a PAYABLE function (typical names: deposit*, stake*, mint*, fund*, buy*, contribute*), then trigger the ETH-sending function so the attacker's receive() callback re-enters. DO NOT default to the names in the example below — they are placeholders.

**Value hints:** Use "0xde0b6b3a7640000" (1 ETH) for payable calls. Use "0x0" for non-payable.

**Valid callers:** "attacker_address"
Use only these alias name(s) in the `caller_name` (msg.sender) slot — there is a
single attacker identity, so every call already runs as the attacker. Never use
"deployer_address" or a raw hex address as a caller. (Address-TYPED ARGUMENTS are
separate: see "Special argument values" below for the aliases those slots accept —
you are NOT restricted to the caller alias there.)
**Strategy notes:** Use "atk.setReentrantCall" as the FIRST call to arm the attacker's re-entry callback: ["atk.setReentrantCall", {"reentrant_func": "fnName", "reentrant_args": ["0x..."], "max_count": 3}, "0x0", "attacker_address"]. The attacker re-enters whenever the target calls BACK into it — either by sending it ETH (receive) or by invoking an unknown selector on it (fallback: e.g. an ERC777/hook/migration callback) — so this covers callback-driven reentrancy too, not just native-ETH transfers. reentrant_func is the function re-called during that callback: a BARE function name from THIS target's ABI (no parentheses, no type list; re-entry always hits the main contract, never an external var). reentrant_args matches that function's input types (use [] if no args). max_count is the re-entry depth (1-5). There is ONE attacker identity: route the arm, the funding/setup AND the final trigger call all through attacker_address (the unified attacker contract) so the callback fires with the attacker as msg.sender.
**Special argument values:**
- address-typed args accept `target_address`, `attacker_address`, or a raw 0x literal.
- `"max"` → uint256 max; `"now"` → block.timestamp.
- `"$ret<idx>"` → feed the RETURN VALUE of the call at 0-based index <idx> in this sequence into this argument (that call must return exactly one value).

**Argument encoding (match each value to its ABI parameter type):**
- uint* / bytesN / bytes → hex string, e.g. "0x1f" (minimal, not zero-padded)
- int* (signed) → decimal string, e.g. "-5"
- bool → true or false (JSON literal, unquoted)
- address → an alias name (see callers/aliases above) or a 40-hex-digit 0x literal
- arrays → JSON list, e.g. [] or ["0x1", "0x2"]; tuples/structs → JSON list of their fields
- empty bytes / empty signature / empty proof → "0x" or []

**Output format:**
Return a JSON array of 1 fuzz input object(s):
[
  {
    "calls": [["functionName", [arg1, arg2], "0x<wei_hex>", "caller_name"], ...],
    "description": "brief description"
  }
]
JSON only — no markdown, no explanation.

**Example sequence:**
```json
Structural pattern (replace UPPERCASE placeholders with real ABI function names):
  [["atk.setReentrantCall", {"reentrant_func": "<ETH_SENDER_FROM_ABI>", "reentrant_args": [], "max_count": 4}, "0x0", "attacker_address"],
   ["<PAYABLE_FUNC_FROM_ABI>", [], "0xde0b6b3a7640000", "attacker_address"],
   ["<PAYABLE_FUNC_FROM_ABI>", [], "0xde0b6b3a7640000", "attacker_address"],
   ["<ETH_SENDER_FROM_ABI>", [], "0x0", "attacker_address"]]
```

